const event = $json.body ?? $json;
const eventId = String(event.event_id ?? event.id ?? '').trim();
const invoiceId = String(event.invoice_id ?? '').trim();
const status = String(event.status ?? '').trim().toLowerCase();

if (!eventId || !invoiceId || !status) {
  return [{
    json: {
      ok: false,
      status: 'invalid',
      error: 'event_id, invoice_id and status are required'
    }
  }];
}

const operationKey = `payment-event:${eventId}`;
const state = $getWorkflowStaticData('global');
state.processed ??= {};

if (state.processed[operationKey]) {
  return [{
    json: {
      ok: true,
      duplicate: true,
      operationKey,
      firstProcessedAt: state.processed[operationKey],
      note: 'Duplicate delivery accepted without repeating downstream side effects.'
    }
  }];
}

const now = new Date().toISOString();
state.processed[operationKey] = now;

return [{
  json: {
    ok: true,
    duplicate: false,
    operationKey,
    accountingUpdate: {
      invoice_id: invoiceId,
      payment_status: status,
      amount: event.amount ?? null,
      currency: event.currency ?? null,
      paid_at: event.paid_at ?? null,
      source_event_id: eventId
    },
    receiptRequest: status === 'paid'
      ? {
          idempotency_key: `receipt:${invoiceId}`,
          invoice_id: invoiceId,
          email: event.customer_email ?? null
        }
      : null,
    processedAt: now
  }
}];
